is_sub_inventory.title:
int32 max_size = 1 [
    (grpc.gateway.protoc_gen_openapiv2.options.openapiv2_field) = {
      description: "Max size of the sub-inventory"
      type: INTEGER
    }
  ];
  repeated string allowed_item_classes = 2 [
    (grpc.gateway.protoc_gen_openapiv2.options.openapiv2_field) = {
      description: "List of allowed item classes in the sub-inventory. If empty, all item classes are allowed"
      type: ARRAY
    }
  ];
  repeated string auto_sort_tags = 3 [
    (grpc.gateway.protoc_gen_openapiv2.options.openapiv2_field) = {
      description: "List of tags to use for auto-sorting items in the sub-inventory. If empty, no auto-sorting is done"
      type: ARRAY
    }
  ];
